                { value: "ready", label: "Ready", icon: "circle" },
              ],
            },
            filterable: true,
            displayable: true,
          },
        ],
        storageKey: `timeline-header-story:${filtered ? "filtered" : "all"}:${obsoleteProperties ? "obsolete" : "current"}`,
      }}
      viewsSource={source}
      search={search}
      onSearchChange={setSearch}
