            url: `/v1/projects/project/session-attachments/${crypto.randomUUID()}/content`,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          }));
          setAttachments((current) => [...current, ...uploaded]);
        }}
      />
    </>
  );
};

