  parameters: { layout: "fullscreen" },
  decorators: [
    (Story) => (
      <QueryClientProvider client={queryClient}>
        <Story />
      </QueryClientProvider>
    ),
  ],
} satisfies Meta;
export default meta;
type Story = StoryObj;
const SidenavStory = (props: { open: (workbench: WorkbenchCore) => void; desktop?: boolean }) => {
