    body: {
      kind: "tree",
      getChildren: () => [],
      getBody: (ctx) => {
        if (publishPartial) ctx?.onProgress?.([]);
        if (failure) throw failure;
        return [{ id: "tools", nodes: [{ id: "notes", label: "Notes" }] }];
      },
    },
  });
  return {
    workbench,
    refresh(error?: Error, partial = false) {
