  args: (() => {
    const workbench = createPolicyWorkbench();
    return {
      workbench,
      panelControlsPlacement: "host" as const,
      titleBar: (
        <WindowTitleBar
          platform="darwin"
          actions={
            <>
              <WorkbenchPanelToggles workbench={workbench} />
              <FullscreenControls workbench={workbench} />
            </>
          }
        >
          <Text textStyle="label/S/medium">Project tabs</Text>
