export const EdgeScrolling: Story = {
  parameters: {
    docs: {
      description: {
        story: "Hold a dragged card near either side of the board to scroll. Moving closer to the edge scrolls faster.",
      },
    },
  },
  render: () => (
    <Box maxW="lg" height="md">
