              asChild
              variant="full-width"
              label="No branches found"
              icon={<Icon as={GitBranch} boxSize="16px" />}
              disabled
            />
          </Menu.Item>
        }
        parentList={{
          items: repositoryItems.map((item) => ({
            ...item,
            isSelected: item.id === selectedRepository,
          })),
          selectedLabel: repositoryLabel,
          selectedIcon: FolderGit2,
          ariaLabel: "Toggle list",
          showSearch: true,
