            </HStack>

            <Box borderWidth="1px" borderColor="border.subtle" borderRadius="md" p="3">
              <Text textStyle="paragraph/S/medium">Navigation output</Text>
              <Text textStyle="paragraph/S/regular" color="fg.muted">
