            </Box>

            <Box borderWidth="1px" borderColor="border.subtle" borderRadius="md" p="3" flex="1">
              <Text textStyle="paragraph/S/regular" color="fg.muted">
                Content area reclaims width when sidenav is hidden.
              </Text>
            </Box>
          </Stack>
